llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C60"],
      "claim": "Urapidil had an absolute oral bioavailability of 78% in healthy volunteers after a 30 mg oral solution, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Moexipril had an oral bioavailability of 22% in normal adult volunteers after oral administration, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Propranolol had an absolute oral bioavailability of 18.9 ± 3.8% after a 20 mg oral dose in normal volunteers, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred absolute oral bioavailability measurements in healthy or normal subjects are ≥20%, including urapidil 78%, moexipril 22%, pethidine 52%, bosentan 50%, metoprolol 40%, encainide 32%, and pamatolol >64%. One propranolol absolute value was 18.9%, but other propranolol absolute values were ≥25%, so the weight of threshold-relevant evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "Propranolol absolute bioavailability is inconsistent across studies (18.9% vs 42.4%), creating uncertainty near the threshold.",
    "Encainide bioavailability varies widely (7–82%) and some qualitative reports describe low values in patients.",
    "Fostemsavir and elagolix are supported only by qualitative 'good bioavailability' statements without numeric F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

